def components(a,val=0,diag=False):
 h,w=a.shape; seen=set(); comps=[]; dirs=[(-1,0),(1,0),(0,-1),(0,1)]
 if diag: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
 for r in range(h):
  for c in range(w):
   if a[r,c]==val and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));cells=[]
    while q:
     x,y=q.pop();cells.append((x,y))
     for dx,dy in dirs:
      z=(x+dx,y+dy)
      if 0<=z[0]<h and 0<=z[1]<w and a[z]==val and z not in seen:seen.add(z);q.append(z)
    comps.append(cells)
 return comps
